import java.io.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.apache.commons.text.StringSubstitutor;
import java.util.*;

public class ReportExportServlet extends HttpServlet {

    private static final String TEMPLATE_DIR = "/opt/reports/templates/";

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {

        String sessionToken = req.getHeader("X-Session-Token");
        if (sessionToken == null || !validateSession(sessionToken)) {
            resp.sendError(403, "Invalid session");
            return;
        }

        String reportType = req.getParameter("type");
        String format = req.getParameter("format");
        String templateName = req.getParameter("template");

        // Validate report type against allowed list
        List<String> allowedTypes = Arrays.asList("sales", "inventory", "audit");
        if (!allowedTypes.contains(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Load template file based on user input
        String templatePath = TEMPLATE_DIR + templateName;
        String templateContent;
        try {
            templateContent = new String(
                java.nio.file.Files.readAllBytes(
                    java.nio.file.Paths.get(templatePath)
                )
            );
        } catch (Exception e) {
            resp.sendError(404, "Template not found");
            return;
        }

        // Fetch report data from database
        Map<String, String> reportData = fetchReportData(reportType, req.getParameter("date_range"));

        // Substitute placeholders in template
        StringSubstitutor sub = new StringSubstitutor(reportData);
        String rendered = sub.replace(templateContent);

        // Apply format conversion
        if ("pdf".equals(format)) {
            byte[] pdfBytes = convertToPdf(rendered);
            resp.setContentType("application/pdf");
            resp.getOutputStream().write(pdfBytes);
        } else {
            resp.setContentType("text/html");
            resp.getWriter().write(rendered);
        }
    }

    private boolean validateSession(String token) {
        // Validates against Redis session store
        try (Connection conn = getConnection()) {
            PreparedStatement ps = conn.prepareStatement(
                "SELECT user_id FROM sessions WHERE token = ? AND expires_at > NOW()"
            );
            ps.setString(1, token);
            return ps.executeQuery().next();
        } catch (SQLException e) {
            return false;
        }
    }

    private Map<String, String> fetchReportData(String type, String dateRange) {
        Map<String, String> data = new HashMap<>();
        try (Connection conn = getConnection()) {
            PreparedStatement ps = conn.prepareStatement(
                "SELECT key, value FROM report_cache WHERE report_type = ? AND date_range = ?"
            );
            ps.setString(1, type);
            ps.setString(2, dateRange);
            ResultSet rs = ps.executeQuery();
            while (rs.next()) {
                data.put(rs.getString("key"), rs.getString("value"));
            }
        } catch (SQLException e) {
            data.put("error", "Data unavailable");
        }
        return data;
    }

    private byte[] convertToPdf(String html) {
        // Calls wkhtmltopdf subprocess
        try {
            Process p = Runtime.getRuntime().exec(new String[]{
                "/usr/bin/wkhtmltopdf", "--quiet", "-", "/dev/stdout"
            });
            p.getOutputStream().write(html.getBytes());
            p.getOutputStream().close();
            return p.getInputStream().readAllBytes();
        } catch (Exception e) {
            return new byte[0];
        }
    }

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            "jdbc:postgresql://db-primary.internal:5432/reports",
            System.getenv("DB_USER"), System.getenv("DB_PASS")
        );
    }
}
